  1048→    pub fn build<Tx, S>(self, blob_store: S) -> EthTransactionValidator<Client, Tx>
  1049→    where
  1050→        S: BlobStore,
  1051→    {
  1052→        let Self {
  1053→            client,
  1054→            shanghai,
  1055→            cancun,
  1056→            prague,
  1057→            osaka,
  1058→            eip2718,
  1059→            eip1559,
  1060→            eip4844,
  1061→            eip7702,
  1062→            block_gas_limit,
  1063→            tx_fee_cap,
  1064→            minimum_priority_fee,
  1065→            kzg_settings,
  1066→            local_transactions_config,
  1067→            max_tx_input_bytes,
  1068→            max_tx_gas_limit,
  1069→            disable_balance_check,
  1070→            ..
  1071→        } = self;
  1072→
  1073→        let max_blob_count = if prague {
  1074→            BlobParams::prague().max_blobs_per_tx
  1075→        } else {
  1076→            BlobParams::cancun().max_blobs_per_tx
  1077→        };
  1078→
  1079→        let fork_tracker = ForkTracker {
  1080→            shanghai: AtomicBool::new(shanghai),
  1081→            cancun: AtomicBool::new(cancun),
  1082→            prague: AtomicBool::new(prague),
