  1091→            fork_tracker,
  1092→            eip4844,
  1093→            eip7702,
  1094→            block_gas_limit,
  1095→            tx_fee_cap,
  1096→            minimum_priority_fee,
  1097→            blob_store: Box::new(blob_store),
  1098→            kzg_settings,
  1099→            local_transactions_config,
  1100→            max_tx_input_bytes,
  1101→            max_tx_gas_limit,
  1102→            disable_balance_check,
  1103→            _marker: Default::default(),
  1104→            validation_metrics: TxPoolValidationMetrics::default(),
