  1193→/// Ensures that gas limit of the transaction exceeds the intrinsic gas of the transaction.
  1194→///
  1195→/// Caution: This only checks past the Merge hardfork.
  1196→pub fn ensure_intrinsic_gas<T: EthPoolTransaction>(
  1197→    transaction: &T,
  1198→    fork_tracker: &ForkTracker,
  1199→) -> Result<(), InvalidPoolTransactionError> {
  1200→    use revm_primitives::hardfork::SpecId;
  1201→    let spec_id = if fork_tracker.is_prague_activated() {
  1202→        SpecId::PRAGUE
  1203→    } else if fork_tracker.is_shanghai_activated() {
  1204→        SpecId::SHANGHAI
  1205→    } else {
  1206→        SpecId::MERGE
  1207→    };
  1208→
  1209→    let gas = revm_interpreter::gas::calculate_initial_tx_gas(
  1210→        spec_id,
  1211→        transaction.input(),
  1212→        transaction.is_create(),
  1213→        transaction.access_list().map(|l| l.len()).unwrap_or_default() as u64,
  1214→        transaction
  1215→            .access_list()
  1216→            .map(|l| l.iter().map(|i| i.storage_keys.len()).sum::<usize>())
  1217→            .unwrap_or_default() as u64,
  1218→        transaction.authorization_list().map(|l| l.len()).unwrap_or_default() as u64,
  1219→    );
  1220→
  1221→    let gas_limit = transaction.gas_limit();
  1222→    if gas_limit < gas.initial_gas || gas_limit < gas.floor_gas {
  1223→        Err(InvalidPoolTransactionError::IntrinsicGasTooLow)
  1224→    } else {
  1225→        Ok(())
  1226→    }
  1227→}
