    52→fn incremental_vs_full_root(inputs: &[&str], modified: &str) {
    53→    let factory = create_test_provider_factory();
    54→    let tx = factory.provider_rw().unwrap();
    55→    let hashed_address = B256::with_last_byte(1);
    56→
    57→    let mut hashed_storage_cursor =
    58→        tx.tx_ref().cursor_dup_write::<tables::HashedStorages>().unwrap();
    59→    let data = inputs.iter().map(|x| B256::from_str(x).unwrap());
    60→    let value = U256::from(0);
    61→    for key in data {
    62→        hashed_storage_cursor.upsert(hashed_address, &StorageEntry { key, value }).unwrap();
    63→    }
    64→
    65→    // Generate the intermediate nodes on the receiving end of the channel
    66→    let (_, _, trie_updates) =
    67→        StorageRoot::from_tx_hashed(tx.tx_ref(), hashed_address).root_with_updates().unwrap();
    68→
    69→    // 1. Some state transition happens, update the hashed storage to the new value
    70→    let modified_key = B256::from_str(modified).unwrap();
    71→    let value = U256::from(1);
    72→    if hashed_storage_cursor.seek_by_key_subkey(hashed_address, modified_key).unwrap().is_some() {
    73→        hashed_storage_cursor.delete_current().unwrap();
    74→    }
    75→    hashed_storage_cursor
    76→        .upsert(hashed_address, &StorageEntry { key: modified_key, value })
    77→        .unwrap();
    78→
    79→    // 2. Calculate full merkle root
    80→    let loader = StorageRoot::from_tx_hashed(tx.tx_ref(), hashed_address);
    81→    let modified_root = loader.root().unwrap();
    82→
    83→    // Update the intermediate roots table so that we can run the incremental verification
    84→    tx.write_individual_storage_trie_updates(hashed_address, &trie_updates).unwrap();
    85→
    86→    // 3. Calculate the incremental root
    87→    let mut storage_changes = PrefixSetMut::default();
    88→    storage_changes.insert(Nibbles::unpack(modified_key));
    89→    let loader = StorageRoot::from_tx_hashed(tx.tx_ref(), hashed_address)
    90→        .with_prefix_set(storage_changes.freeze());
    91→    let incremental_root = loader.root().unwrap();
    92→
    93→    assert_eq!(modified_root, incremental_root);
    94→}
