   104→        let (current_fork_idx, current_fork_timestamp) = fork_timestamps
   105→            .iter()
   106→            .position(|ts| &latest.timestamp < ts)
   107→            .and_then(|idx| idx.checked_sub(1))
   108→            .or_else(|| fork_timestamps.len().checked_sub(1))
